    // CoPilot - GPT-6 (generated by Codex)
    [Theory]
    [InlineData (4)]
    [InlineData (11)]
    [InlineData (35)]
    public void UnixTransientFailure_RetriesExactUnwrittenTail (int error)
    {
        if (error != 4 && error != (OperatingSystem.IsMacOS () || OperatingSystem.IsFreeBSD () ? 35 : 11))
        {
            return;
        }

        List<string> tails = [];
        int calls = 0;
        bool success = UnixIOHelper.TryWriteAll (1, "ABC"u8, (_, bytes) =>
        {
            tails.Add (Encoding.UTF8.GetString (bytes));
            calls++;
            return calls == 2 ? -1 : 1;
        }, () => error);

        Assert.True (success);
        Assert.Equal (["ABC", "BC", "BC", "C"], tails);
    }

