    // Claude - Opus 5.5
    [Fact]
    public void UnixTransientFailuresBetweenProgress_DoNotAbortWrite ()
    {
        List<byte> written = [];
        int calls = 0;

        // Every byte is preceded by EINTR: 32 interruptions in total, but never more than one in a row.
        bool success = UnixIOHelper.TryWriteAll (1, Encoding.UTF8.GetBytes (new string ('x', 32)), (_, bytes) =>
        {
            if (calls++ % 2 == 0)
            {
                return -1;
            }

            written.Add (bytes [0]);

            return 1;
        }, () => 4);

        Assert.True (success);
        Assert.Equal (32, written.Count);
    }

