    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void ApplicationDraw_RetriesPhysicalFailureWithoutAnotherViewDraw ()
    {
        using IApplication app = Application.Create ().Init (DriverRegistry.Names.ANSI);
        IDriver originalDriver = app.Driver!;
        bool fail = false;
        List<string> writes = [];
        AnsiOutput output = new (bytes =>
        {
            if (fail)
            {
                return false;
            }

            writes.Add (Encoding.UTF8.GetString (bytes));
            return true;
        });
        OutputBufferImpl buffer = new ();
        buffer.SetSize (10, 2);
        using DriverImpl driver = CreateDriver (output, buffer);
        app.Driver = driver;
        using Runnable runnable = new () { Width = 10, Height = 2 };
        SessionToken owner = app.Begin (runnable)!;

        try
        {
            app.LayoutAndDraw ();
            writes.Clear ();
            buffer.Move (0, 0);
            buffer.AddStr ("RECOVER");
            fail = true;
            driver.Refresh ();
            Assert.True (driver.NeedsOutputRetry);
            Assert.False (runnable.NeedsDraw);
            Assert.False (runnable.SubViewNeedsDraw);
            fail = false;
            app.LayoutAndDraw ();
            Assert.False (driver.NeedsOutputRetry);
            Assert.Contains ("RECOVER", Assert.Single (writes));
        }
        finally
        {
            app.End (owner);
            app.Driver = originalDriver;
        }
    }

