    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void AnsiLargeText_ReusesBoundedEncodingAndPreservesSurrogateBoundaries ()
    {
        string payload = new string ('a', 16383) + "😀" + new string ('中', 1024 * 1024);
        StringBuilder received = new ();
        bool collect = false;
        AnsiOutput output = new (bytes =>
        {
            if (collect)
            {
                received.Append (Encoding.UTF8.GetString (bytes));
            }

            return true;
        }) { CaptureOutput = false };
        output.Write (payload.AsSpan ());
        long before = GC.GetAllocatedBytesForCurrentThread ();
        output.Write (payload.AsSpan ());
        long allocated = GC.GetAllocatedBytesForCurrentThread () - before;
        collect = true;
        output.Write (payload.AsSpan ());
        Assert.Equal (payload, received.ToString ());
        Assert.InRange (allocated, 0, 1024);
    }

    // CoPilot - GPT-6 (generated by Codex)
    [Fact]
    public void PerCellColoredFrame_StreamsWithoutRepeatedMegabyteAllocations ()
    {
        int writes = 0;
        int bytesWritten = 0;
        int largestWrite = 0;
        AnsiOutput output = new (bytes =>
        {
            writes++;
            bytesWritten += bytes.Length;
            largestWrite = Math.Max (largestWrite, bytes.Length);
            return true;
        }) { CaptureOutput = false };
        OutputBufferImpl buffer = new ();
        buffer.SetSize (400, 110);

        for (int row = 0; row < buffer.Rows; row++)
        {
            for (int col = 0; col < buffer.Cols; col++)
            {
                buffer.Move (col, row);
                buffer.CurrentAttribute = new (new Color (col % 256, row % 256, (row + col) % 256), Color.Black);
                buffer.AddRune ('A');
            }
        }

        output.Write (buffer);
        for (int row = 0; row < buffer.Rows; row++)
        {
            buffer.DirtyLines [row] = true;
            for (int col = 0; col < buffer.Cols; col++)
            {
                buffer.Contents! [row, col].IsDirty = true;
            }
        }

        writes = 0;
        bytesWritten = 0;
        largestWrite = 0;
        long before = GC.GetAllocatedBytesForCurrentThread ();
        output.Write (buffer);
        long allocated = GC.GetAllocatedBytesForCurrentThread () - before;
        Assert.True (writes >= 2);
        Assert.True (bytesWritten > Utf8Buffer.RetainedCapacityLimit);
        Assert.InRange (largestWrite, 1, Utf8Buffer.RetainedCapacityLimit);
        // GetColumns currently allocates per grapheme (~12 MB for this frame). Allow that
        // existing cost, but reject the additional ~4 MB from repeated oversized staging.
        Assert.InRange (allocated, 0, 14 * 1024 * 1024);
    }

