    private static DriverImpl CreateDriver (AnsiOutput output, OutputBufferImpl buffer) => new (
        new AnsiComponentFactory (), new AnsiInputProcessor (null!), buffer, output,
        new (new AnsiResponseParser (new SystemTimeProvider ())), new SizeMonitorImpl (output));

    private sealed class CaptureOnlyOutput : OutputBase
    {
        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;
        public void WriteBytes (ReadOnlySpan<byte> bytes) => Write (bytes);
    }

    private sealed class ForwardingAnsiOutput (AnsiOutput.UnixWriter writer) : AnsiOutput (writer)
    {
        public int Calls { get; private set; }
        protected override bool SetCursorPositionImpl (int col, int row) => true;
        protected override void Write (StringBuilder output)
        {
            if (++Calls > 4) throw new InvalidOperationException ("recursive fallback");
            Write (Encoding.UTF8.GetBytes (output.ToString ()));
        }
    }

    private sealed class ForwardingNetOutput : NetOutput
    {
        public int Calls { get; private set; }
        protected override bool SetCursorPositionImpl (int col, int row) => true;
        protected override void Write (StringBuilder output)
        {
            if (++Calls > 4) throw new InvalidOperationException ("recursive fallback");
            Write (Encoding.UTF8.GetBytes (output.ToString ()));
        }
    }

    private sealed class ForwardingLegacyOutput : OutputBase
    {
        public int Calls { get; private set; }
        protected override bool SetCursorPositionImpl (int screenPositionX, int screenPositionY) => true;
        protected override void Write (StringBuilder output)
        {
            Calls++;
            if (Calls > 2)
            {
                throw new InvalidOperationException ("recursive fallback");
            }

            Write (Encoding.UTF8.GetBytes (output.ToString ()));
        }
    }
